"use client";
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { AiOutlineSearch, AiOutlineUser, AiOutlineShoppingCart } from "react-icons/ai";
import { useRouter } from "next/navigation";
import Image from "next/image"; // 👈 Next.js Image import
import logo from "@/assets/logo.jpg"; // 👈 Local image import

export default function Navbar() {
  const [openMenu, setOpenMenu] = useState(false);
  const router = useRouter();

  return (
    <nav className="fixed top-0 left-0 w-full text-white z-50">
      <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">
        {/* Left: Logo & Name */}
        <div
          className="flex items-center gap-2 cursor-pointer select-none"
          onClick={() => router.push("/")}
        >
          <motion.div
            whileHover={{ rotate: 10, scale: 1.1 }}
            transition={{ type: "spring", stiffness: 300 }}
          >
            <Image
              src={logo}
              alt="MultiCart Logo"
              width={40}
              height={40}
              className="rounded-full object-cover"
              priority
            />
          </motion.div>
          <span className="text-2xl font-semibold text-gray-00">MultiCart</span>
        </div>

        {/* Right: Icons */}
        <div className="flex items-center gap-6">
          {/* Search Icon */}
          <motion.button
            whileHover={{ scale: 1.1 }}
            className="text-gray-300 hover:text-white transition"
            onClick={() => alert("Search feature coming soon 🔍")}
          >
            <AiOutlineSearch size={24} />
          </motion.button>

          {/* Profile Icon */}
          <div className="relative">
            <motion.button
              whileHover={{ scale: 1.1 }}
              className="text-gray-300 hover:text-white transition"
              onClick={() => setOpenMenu(!openMenu)}
            >
              <AiOutlineUser size={24} />
            </motion.button>

            {/* Dropdown Menu */}
            <AnimatePresence>
              {openMenu && (
                <motion.div
                  key="menu"
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.2 }}
                  className="absolute right-0 mt-3 w-40  backdrop-blur-md rounded-xl shadow-lg border border-white/20 overflow-hidden"
                >
                  <button
                    onClick={() => {
                      setOpenMenu(false);
                      router.push("/profile");
                    }}
                    className="block w-full text-left px-4 py-2 text-sm hover:bg-white/20 transition"
                  >
                    ✏️ Edit Profile
                  </button>
                  <button
                    onClick={() => {
                      setOpenMenu(false);
                      router.push("/login");
                    }}
                    className="block w-full text-left px-4 py-2 text-sm hover:bg-white/20 transition"
                  >
                    🔐 Login
                  </button>
                  <button
                    onClick={() => {
                      setOpenMenu(false);
                      router.push("/signup");
                    }}
                    className="block w-full text-left px-4 py-2 text-sm hover:bg-white/20 transition"
                  >
                    📝 Sign Up
                  </button>
                </motion.div>
              )}
            </AnimatePresence>
          </div>

          {/* Cart Icon */}
          <motion.button
            whileHover={{ scale: 1.1 }}
            className="text-gray-300 hover:text-white transition relative"
            onClick={() => router.push("/cart")}
          >
            <AiOutlineShoppingCart size={24} />
            <span className="absolute -top-2 -right-2 text-xs bg-blue-500 text-white rounded-full px-1">
              3
            </span>
          </motion.button>
        </div>
      </div>
    </nav>
  );
}
